<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_admin();
require_once __DIR__.'/../account_service.php';
handle_post(fn()=>manage_account($_POST),'users.php');
$where=['1=1'];$params=[];$q=trim(request_string($_GET,'q'));if($q!==''){$where[]='(full_name LIKE ? OR username LIKE ?)';array_push($params,'%'.$q.'%','%'.$q.'%');}
foreach(['role'=>['Administrator','Faculty','Student'],'registration_status'=>['Pending','Approved','Rejected'],'is_active'=>['0','1']]as $key=>$allowed){$v=request_string($_GET,$key);if($v!==''){if(!in_array($v,$allowed,true))throw new DomainException('Invalid user filter.');$where[]="$key=?";$params[]=$v;}}
$dates=date_filters($_GET);foreach(['from'=>'>=','to'=>'<=']as $key=>$operator)if(isset($dates[$key])){$where[]="DATE(created_at)$operator?";$params[]=$dates[$key];}
$filter=implode(' AND ',$where);$total=(int)scalar("SELECT COUNT(*) FROM users WHERE $filter",$params);$page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/15)));$offset=($page-1)*15;$data=rows("SELECT u.id,u.full_name,u.username,u.email,u.role,u.student_id,u.is_active,u.registration_status,u.must_change_password,u.last_seen_at,(SELECT CONCAT(st.student_number,' · ',st.full_name) FROM students st WHERE st.id=u.student_id) linked_student FROM users u WHERE $filter ORDER BY id DESC LIMIT 15 OFFSET $offset",$params);
page_start('User management','Approve registrations, assign roles, and manage account access.');
?><section class="panel no-print"><form method="get" class="filter-grid"><?php input_field('q','Name / username',$q,'search',false);select_field('role','Role',['Administrator'=>'Administrator','Faculty'=>'Faculty','Student'=>'Student'],$_GET['role']??'',false);select_field('registration_status','Approval',['Pending'=>'Pending','Approved'=>'Approved','Rejected'=>'Rejected'],$_GET['registration_status']??'',false);select_field('is_active','Account status',[1=>'Active',0=>'Inactive'],$_GET['is_active']??'',false);input_field('from','Created from',$_GET['from']??'','date',false);input_field('to','Created to',$_GET['to']??'','date',false);?><div class="field align-self-end"><button class="btn btn-outline-primary">Filter</button></div></form></section><details class="panel no-print"><summary>Create an account</summary><form method="post" class="form-grid mt-3"><?php csrf_field();input_field('full_name','Full name');input_field('username','Username');input_field('password','Temporary password (10–72 bytes)','','password');select_field('role','Role',['Faculty'=>'Faculty','Student'=>'Student','Administrator'=>'Administrator'],'Faculty');select_field('student_id','Student academic record (Student accounts only)',choices('students','student_number'),'',false);?><button class="btn btn-primary" name="action" value="create">Create account</button></form></details><section class="panel"><?php data_table($data,['id'=>'ID','full_name'=>'Full name','username'=>'Username','role'=>'Role','linked_student'=>'Academic record','registration_status'=>'Approval','is_active'=>'Active','last_seen_at'=>'Last activity'],function($u){if((int)$u['id']===(int)current_user()['id']){echo 'Current account';return;}if($u['registration_status']==='Pending'){post_button('approve',(int)$u['id'],'Approve');post_button('reject',(int)$u['id'],'Reject','Reject this registration?');}else post_button('toggle',(int)$u['id'],'Activate / deactivate','Change account access immediately?');?><?php if($u['role']==='Student'):?><details class="mt-2"><summary>Verify student link</summary><p class="small text-secondary">Verify identity before selecting a record. The existing session will be revoked.</p><form method="post" class="form-grid" data-confirm="Change this account’s academic-record link and revoke its sessions?"><?php csrf_field();?><input type="hidden" name="id" value="<?=(int)$u['id']?>"><?php select_field('student_id','Verified student academic record',choices('students','student_number'),$u['student_id']??'',false);?><button class="btn btn-sm btn-outline-primary" name="action" value="link">Save verified link</button></form></details><?php endif;?><details class="mt-2"><summary>Reset password / change role</summary><form method="post" class="form-grid"><?php csrf_field();?><input type="hidden" name="id" value="<?=(int)$u['id']?>"><?php input_field('password','New temporary password','','password');?><button class="btn btn-sm btn-outline-primary" name="action" value="reset">Reset password</button></form><form method="post" class="form-grid" data-confirm="Change this account’s role and invalidate its sessions?"><?php csrf_field();?><input type="hidden" name="id" value="<?=(int)$u['id']?>"><?php select_field('role','Role',['Administrator'=>'Administrator','Faculty'=>'Faculty','Student'=>'Student'],$u['role']);?><button class="btn btn-sm btn-outline-secondary" name="action" value="role">Change role</button></form></details><?php });pagination($total,$page);?></section><?php page_end();
